/*
# Feature Upgrade — Theme Settings, Hero Controls & Luxury Dummy Products

## What this migration does

1. **New store_settings columns** for the light/dark theme + hero controls:
   - `default_theme` (text, 'dark' | 'light', default 'dark') — admin-chosen default
   - `theme_toggle_visible` (boolean, default true) — show/hide the header toggle
   - `hero_overlay_opacity` (integer 0–100, default 65) — darkness of hero gradient
   - `hero_brightness` (integer 50–150, default 100) — hero image brightness %
   - `hero_parallax` (boolean, default true) — enable parallax scroll on hero
2. **store_settings_public view** dropped and recreated with the new columns.
3. **~120 luxury dummy products** seeded across all 15 sub-categories with
   high-resolution Pexels imagery, BDT pricing, discount badges, ratings, stock,
   colors/sizes, and rich descriptions. Fixed UUIDs + ON CONFLICT DO NOTHING
   make the migration idempotent.

## Security
- No RLS / policy changes. Existing product policies cover the seeded rows.
*/

-- ========== New settings columns ==========
ALTER TABLE public.store_settings
  ADD COLUMN IF NOT EXISTS default_theme text NOT NULL DEFAULT 'dark';
ALTER TABLE public.store_settings
  ADD COLUMN IF NOT EXISTS theme_toggle_visible boolean NOT NULL DEFAULT true;
ALTER TABLE public.store_settings
  ADD COLUMN IF NOT EXISTS hero_overlay_opacity integer NOT NULL DEFAULT 65;
ALTER TABLE public.store_settings
  ADD COLUMN IF NOT EXISTS hero_brightness integer NOT NULL DEFAULT 100;
ALTER TABLE public.store_settings
  ADD COLUMN IF NOT EXISTS hero_parallax boolean NOT NULL DEFAULT true;

-- Drop and recreate the anon-safe public view to include the new columns.
DROP VIEW IF EXISTS public.store_settings_public;
CREATE VIEW public.store_settings_public AS
SELECT
  id, store_name, tagline, phone, email, address,
  facebook_url, instagram_url, tiktok_url, whatsapp_url,
  primary_color, secondary_color, accent_color, bg_color,
  button_depth, card_shadow, hover_zoom, border_radius,
  facebook_pixel_id, tiktok_pixel_id, gtm_id, ga4_id, clarity_id,
  card_enabled, cod_enabled, bdt_to_usd_rate, gemini_system_prompt,
  fraud_shield_enabled,
  bkash_instructions, nagad_instructions, rocket_instructions, rocket_number,
  card_instructions, cod_instructions, binance_instructions,
  hero_banners, hero_overlay_opacity, hero_brightness, hero_parallax,
  default_theme, theme_toggle_visible,
  policy_return, policy_authentic, policy_shipping, policy_warranty,
  policy_support, default_courier, updated_at
FROM store_settings;

